// Match the incoming event to a trigger, and check audience eligibility.
// NOTE: this config MIRRORS config/triggers.yml + config/audience.yml. n8n
// Code nodes cannot import repo files, so the config is inlined here. Keep the
// two in sync (the offline harness in src/ reads the YAML directly).

const TRIGGERS = [
  { id: 'activation-nudge', event: 'core_action_completed', property_filters: {}, threshold: 5, window: '7d',
    frequency: { cooldown: '30d', max_per_person: 1, lookback: '90d' },
    negative_conditions: [{ event: 'upgraded_plan' }, { event: 'contacted_by_sales' }], template: 'activation-nudge' },
  { id: 'feature-adoption', event: 'advanced_feature_used', property_filters: { feature: 'reports' }, threshold: 10, window: '14d',
    frequency: { cooldown: '45d', max_per_person: 2, lookback: '180d' },
    negative_conditions: [], template: 'feature-adoption' },
  { id: 'usage-limit-approaching', event: 'quota_consumed', property_filters: {}, threshold: 6, window: '30d',
    frequency: { cooldown: '14d', max_per_person: 3, lookback: '90d' },
    negative_conditions: [{ event: 'upgraded_plan' }], template: 'usage-limit' },
];
const AUDIENCE = {
  include: { plans: [] },
  exclude: { email_domains: ['example.com', 'test.local', 'yourcompany.com'], emails: [], suppression: ['optout@nimbusworks.io', 'donotcontact@dataloom.io'] },
  require: { has_email: true, marketing_consent: false },
};

function parseDur(s) { const m = /^(\d+)\s*([hd])$/.exec(String(s).trim()); const n = +m[1]; return m[2] === 'h' ? n * 3600e3 : n * 86400e3; }

const b = $json.body || $json;
const eventName = b.event;
const props = b.properties || {};
const person = {
  email: (props.email || '').toLowerCase(),
  name: props.name || '',
  company: props.company || '',
  plan: props.plan || '',
  marketingConsent: props.marketing_consent === true || props.marketing_consent === 'true',
};
const distinctId = b.distinct_id;

function fail(reason) { return [{ json: { proceed: false, reason, person, distinctId, eventName } }]; }

// audience
if (AUDIENCE.require.has_email && !person.email) return fail('no-email');
if (AUDIENCE.require.marketing_consent && !person.marketingConsent) return fail('no-marketing-consent');
const domain = person.email.split('@')[1] || '';
if (AUDIENCE.exclude.email_domains.map(d => d.toLowerCase()).includes(domain)) return fail('excluded-domain:' + domain);
if (AUDIENCE.exclude.emails.map(e => e.toLowerCase()).includes(person.email)) return fail('excluded-email');
if (AUDIENCE.exclude.suppression.map(e => e.toLowerCase()).includes(person.email)) return fail('suppressed');
if (AUDIENCE.include.plans.length && !AUDIENCE.include.plans.includes(person.plan)) return fail('plan-not-in-scope:' + person.plan);

// match trigger (first whose event + property_filters match this event)
const trigger = TRIGGERS.find(t => t.event === eventName && Object.entries(t.property_filters).every(([k, v]) => props[k] === v));
if (!trigger) return fail('no-matching-trigger:' + eventName);

// build the HogQL that counts the trigger event and any negative events in the window
const windowHours = parseDur(trigger.window) / 3600e3;
const negEvents = (trigger.negative_conditions || []).map(c => c.event);
const negList = negEvents.length ? negEvents.map(e => "'" + e + "'").join(',') : "''";
const propClause = Object.entries(trigger.property_filters).map(([k, v]) => " AND properties." + k + " = '" + v + "'").join('');
const hogql =
  "SELECT countIf(event = '" + trigger.event + "'" + propClause + ") AS trigger_count, " +
  "countIf(event IN (" + negList + ")) AS negative_count " +
  "FROM events WHERE distinct_id = '" + distinctId + "' " +
  "AND timestamp >= now() - INTERVAL " + windowHours + " HOUR";

return [{ json: { proceed: true, reason: 'matched', distinctId, eventName, person,
  trigger: { id: trigger.id, event: trigger.event, threshold: trigger.threshold, window: trigger.window,
             frequency: trigger.frequency, template: trigger.template },
  hogql } }];

// Read PostHog's count result, apply threshold + negative + cooldown/frequency.
const prev = $('Match Trigger & Audience').item.json;
const trigger = prev.trigger;

// PostHog query API returns { results: [[trigger_count, negative_count]] }.
let triggerCount = 0, negativeCount = 0;
try {
  const r = $json.results || $json.result || [];
  if (r[0]) { triggerCount = Number(r[0][0]) || 0; negativeCount = Number(r[0][1]) || 0; }
} catch (e) {}

function parseDur(s) { const m = /^(\d+)\s*([hd])$/.exec(String(s).trim()); const n = +m[1]; return m[2] === 'h' ? n * 3600e3 : n * 86400e3; }
const now = Date.now();
const out = { ...prev, triggerCount, negativeCount };

if (triggerCount < trigger.threshold) return [{ json: { ...out, fire: false, reason: 'below-threshold:' + triggerCount + '/' + trigger.threshold } }];
if (negativeCount > 0) return [{ json: { ...out, fire: false, reason: 'negative-condition-present' } }];

// Cooldown / frequency cap using workflow static data.
// NOTE: workflow static data is a BASIC durable store (per-workflow). For
// production, swap this for Postgres/Redis so caps survive across workflows and
// instances. Mirrors the offline harness's send-history logic.
const store = $getWorkflowStaticData('global');
store.sends = Array.isArray(store.sends) ? store.sends : [];
const key = prev.person.email || prev.distinctId;
const mine = store.sends.filter(s => s.key === key && s.triggerId === trigger.id);
const f = trigger.frequency || {};
if (f.cooldown) { const cut = now - parseDur(f.cooldown); if (mine.some(s => s.at >= cut)) return [{ json: { ...out, fire: false, reason: 'cooldown:' + f.cooldown } }]; }
if (f.max_per_person != null && f.lookback) { const cut = now - parseDur(f.lookback); if (mine.filter(s => s.at >= cut).length >= f.max_per_person) return [{ json: { ...out, fire: false, reason: 'frequency-cap' } }]; }

return [{ json: { ...out, fire: true, reason: 'fire' } }];

// Build the LiteLLM prompt from the matched trigger's template + usage context.
// Template text is inlined here (mirrors config/templates/*.md). Keep in sync.
const TEMPLATES = {
  'activation-nudge':
    'You are a product specialist writing a short, genuinely helpful message to a user who is actively using the product. Do not be salesy. Reference their real usage. No discounts, no urgency, no hype.',
  'feature-adoption':
    'You are a product specialist writing to a user who has been heavily using an advanced feature. Be concise and useful, not promotional.',
  'usage-limit':
    'You are a product specialist writing to a user approaching a plan/usage limit. Be helpful and factual. Do not pressure them. Do not invent specific prices or limits.',
};
const d = $json;
const first = (d.person.name || '').trim().split(/\s+/)[0] || 'there';
const sys = TEMPLATES[d.trigger.template] || TEMPLATES['activation-nudge'];
const userMsg =
  'Context:\n' +
  '- User: ' + first + ' at ' + (d.person.company || 'your team') + ' (plan: ' + (d.person.plan || 'unknown') + ')\n' +
  '- Signal: "' + d.trigger.event + '" reached ' + d.triggerCount + ' in the last ' + d.trigger.window + '\n\n' +
  'Write 3-4 sentences that acknowledge specifically what they have been doing, offer one concrete next step, and end with a low-pressure open question. Return only the message body.';
return [{ json: { ...d, firstName: first, llm: { system: sys, user: userMsg } } }];

// Persist the send so cooldown/frequency caps apply next time.
const store = $getWorkflowStaticData('global');
store.sends = Array.isArray(store.sends) ? store.sends : [];
const d = $('Build Prompt').item.json;
store.sends.push({ key: d.person.email || d.distinctId, triggerId: d.trigger.id, at: Date.now() });
return [{ json: { recorded: true, key: d.person.email || d.distinctId, triggerId: d.trigger.id } }];
